# 70-question 7-range parallel runner
# 用 Start-Process 后台跑 7 个 node 进程，每个写一个独立 output 目录
# 用 lock 文件标记完成

$ErrorActionPreference = 'Stop'
Set-Location 'd:\桌面\comparison-experiment-main'

# (1-indexed start, 1-indexed end, output dir name)
$ranges = @(
  @{ start=1;   end=10;  dir='range-001-010' }
  @{ start=30;  end=40;  dir='range-030-040' }
  @{ start=70;  end=80;  dir='range-070-080' }
  @{ start=100; end=110; dir='range-100-110' }
  @{ start=160; end=170; dir='range-160-170' }
  @{ start=250; end=260; dir='range-250-260' }
  @{ start=290; end=300; dir='range-290-300' }
)

# 1-indexed -> 0-indexed offset, LIMIT = (end-start+1)
$jobs = @()
foreach ($r in $ranges) {
  $offset = $r.start - 1
  $limit  = $r.end - $r.start + 1
  $dir    = $r.dir
  $outDir = Join-Path 'output' $dir
  $doneFile = Join-Path $outDir 'DONE.flag'
  if (Test-Path $doneFile) { Remove-Item $doneFile -Force }

  # 干净起见：删掉旧 run
  if (Test-Path $outDir) { Remove-Item $outDir -Recurse -Force }

  $logFile = Join-Path $outDir 'stdout.log'
  $null = New-Item -ItemType Directory -Path $outDir -Force

  $args = @(
    'ablation.js',
    '--mode', 'recall',
    '--limit',  $limit,
    '--offset', $offset,
    '--enable-thinking-recall',  'false',
    '--enable-thinking-reasoning','false',
    '--api-key', 'sk-d6ceb121d4cc49509546f62544cefe53',
    '--output',  "./output/$dir"
  )

  Write-Host "Launching: $($r.start)-$($r.end)  (offset=$offset limit=$limit) -> $outDir"

  $proc = Start-Process -FilePath 'node' -ArgumentList $args -RedirectStandardOutput $logFile -RedirectStandardError "$logFile.err" -NoNewWindow -PassThru
  $jobs += [pscustomobject]@{
    start=$r.start; end=$r.end; dir=$dir; pid=$proc.Id; doneFile=$doneFile; logFile=$logFile
  }
}

Write-Host "`nAll 7 jobs launched. Waiting..."
foreach ($j in $jobs) {
  Write-Host "  PID=$($j.pid)  $($j.start)-$($j.end)  dir=$($j.dir)"
}
Write-Host ""

# 轮询每个进程的 doneFile / 进程退出
$deadline = (Get-Date).AddHours(2)
while (($jobs | Where-Object { -not (Test-Path $_.doneFile) }).Count -gt 0 -and (Get-Date) -lt $deadline) {
  Start-Sleep -Seconds 10
  foreach ($j in $jobs) {
    if ((Test-Path $j.doneFile)) { continue }
    $p = Get-Process -Id $j.pid -ErrorAction SilentlyContinue
    if (-not $p) {
      # 进程已退出但没写 doneFile -> 失败
      Write-Host "[WARN] PID $($j.pid) ($($j.start)-$($j.end)) exited WITHOUT doneFile"
      # 写一个失败标志，结束等待
      "FAILED" | Out-File $j.doneFile -Encoding utf8
    }
  }
  $remaining = ($jobs | Where-Object { -not (Test-Path $_.doneFile) }).Count
  Write-Host "[$(Get-Date -Format 'HH:mm:ss')] $remaining / $($jobs.Count) still running..."
}

# 收尾：每个 job 写一个 done 标志（如果还没写）
foreach ($j in $jobs) {
  if (-not (Test-Path $j.doneFile)) {
    $p = Get-Process -Id $j.pid -ErrorAction SilentlyContinue
    if (-not $p) { "EXITED" | Out-File $j.doneFile -Encoding utf8 }
  }
}

Write-Host "`n=== All jobs finished ==="
foreach ($j in $jobs) {
  $ok = (Test-Path $j.doneFile) -and ((Get-Content $j.doneFile) -ne 'FAILED')
  $flag = if ($ok) { 'OK' } else { 'FAIL' }
  Write-Host "  [$flag] $($j.start)-$($j.end)  $($j.dir)"
}

