      }
      while ($j.stderr.Peek() -ne -1) {
        $j.stderr.ReadLine() | Out-File -FilePath "$($j.log).err" -Append -Encoding utf8
      }
      $remaining++
    }
  }
  if ($remaining -gt 0) {
    Write-Host "[$(Get-Date -Format 'HH:mm:ss')] $remaining / $($jobs.Count) still running..."
