  $sumFile = Join-Path 'output' $j.dir 'recall-summary.json'
  $detFile = Join-Path 'output' $j.dir 'recall-details.json'
  $ok = $j.finished -and (Test-Path $sumFile) -and (Test-Path $detFile)
  $flag = if ($ok) { 'OK' } else { 'FAIL' }
  if ($ok) {
    $sum = Get-Content $sumFile -Raw | ConvertFrom-Json
    $detCount = (Get-Content $detFile -Raw | ConvertFrom-Json).Count
    Write-Host ("  [{0}] {1}-{2}  {3,-14}  EM={4,5:F1}%  ({5}/{6})  recall cache={7:F1}%" -f `
      $flag, $j.start, $j.end, $j.dir, ($sum.averageScore*100), $sum.exactMatches, $sum.total, ($sum.recallUsage.cacheHitRate*100))
  } else {
    Write-Host "  [$flag] $($j.start)-$($j.end)  $($j.dir)"
  }
}

