const fs = require('fs');
const base = 'D:/桌面/comparison-experiment-main/拓扑链的300个样本测试';
function walk(dir, prefix='') {
  const entries = fs.readdirSync(dir, { withFileTypes: true }).sort((a,b)=>a.name.localeCompare(b.name));
  for (const e of entries) {
    const full = dir + '/' + e.name;
    if (e.isDirectory()) { console.log(prefix + e.name + '/'); walk(full, prefix + '  '); }
    else { const sz = fs.statSync(full).size; console.log(prefix + e.name + '  (' + sz + 'b)'); }
  }
}
walk(base);
"
